// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"Por que falar de ética","html":"<p>Quem trabalha na escola pública serve à população e convive todos os dias com crianças e adolescentes. Cada atitude, da portaria à direção, ensina alguma coisa.</p><p>Este guia apresenta os princípios comuns a todos e as condutas esperadas de cada função. Ele não substitui o estatuto do servidor nem as normas da rede. Ajuda a aplicá-los no dia a dia.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>O que significa na escola</th></tr></thead><tbody><tr><td data-rotulo=\"Princípio\">Legalidade</td><td data-rotulo=\"O que significa na escola\">Agir conforme a lei e as normas da rede.</td></tr><tr><td data-rotulo=\"Princípio\">Impessoalidade</td><td data-rotulo=\"O que significa na escola\">Tratar todos da mesma forma, sem favorecer nem perseguir.</td></tr><tr><td data-rotulo=\"Princípio\">Moralidade</td><td data-rotulo=\"O que significa na escola\">Agir com honestidade, mesmo quando ninguém vê.</td></tr><tr><td data-rotulo=\"Princípio\">Publicidade</td><td data-rotulo=\"O que significa na escola\">Dar transparência aos atos, respeitando o sigilo dos dados pessoais.</td></tr><tr><td data-rotulo=\"Princípio\">Eficiência</td><td data-rotulo=\"O que significa na escola\">Cuidar do tempo, dos recursos e do resultado do trabalho.</td></tr><tr><td data-rotulo=\"Princípio\">Prioridade da criança e do adolescente</td><td data-rotulo=\"O que significa na escola\">Colocar a proteção e a aprendizagem do aluno em primeiro lugar.</td></tr></tbody></table></div><div class=\"nota\"><b>Base legal</b><br/>Constituição Federal, art. 37 (princípios da administração pública) e art. 227 (prioridade absoluta da criança e do adolescente); Estatuto da Criança e do Adolescente; Lei Geral de Proteção de Dados; estatuto do servidor e normas do Município.</div>"},{"id":"c2","titulo":"Compromissos de todos","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Compromisso</th><th>Na prática</th></tr></thead><tbody><tr><td data-rotulo=\"Compromisso\">Respeito</td><td data-rotulo=\"Na prática\">Tratar alunos, responsáveis e colegas com educação, sem gritos, apelidos ou humilhação.</td></tr><tr><td data-rotulo=\"Compromisso\">Proteção</td><td data-rotulo=\"Na prática\">Nunca ficar indiferente a sinais de violência contra um aluno. Comunicar à direção.</td></tr><tr><td data-rotulo=\"Compromisso\">Sigilo</td><td data-rotulo=\"Na prática\">Não comentar a vida de alunos, famílias e colegas fora do necessário para o trabalho.</td></tr><tr><td data-rotulo=\"Compromisso\">Igualdade</td><td data-rotulo=\"Na prática\">Não discriminar por cor, origem, religião, deficiência, gênero, aparência ou condição social.</td></tr><tr><td data-rotulo=\"Compromisso\">Honestidade</td><td data-rotulo=\"Na prática\">Não usar o cargo, o tempo ou os bens da escola em benefício próprio.</td></tr><tr><td data-rotulo=\"Compromisso\">Presença</td><td data-rotulo=\"Na prática\">Cumprir horário e avisar com antecedência quando não puder comparecer.</td></tr><tr><td data-rotulo=\"Compromisso\">Exemplo</td><td data-rotulo=\"Na prática\">Lembrar que os alunos observam como os adultos falam e agem.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Limites no contato com alunos</b><br/>Não se dá carona a aluno sozinho, não se mantém conversa particular com aluno em rede social, não se pede segredo a aluno, não se aceita nem se oferece presente de valor. Contatos fora da escola passam pelos responsáveis e pelos canais da escola.</div>"},{"id":"c3","titulo":"Conduta de cada função","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Função</th><th>Compromissos específicos</th></tr></thead><tbody><tr><td data-rotulo=\"Função\">Professor</td><td data-rotulo=\"Compromissos específicos\">Ensinar a todos. Avaliar com justiça. Não expor alunos. Planejar e registrar. Participar das reuniões. Não fazer propaganda política, comercial ou religiosa em sala.</td></tr><tr><td data-rotulo=\"Função\">Coordenação pedagógica</td><td data-rotulo=\"Compromissos específicos\">Apoiar os professores. Usar dados para orientar, e não para classificar. Tratar com reserva o que ouve de professores e famílias.</td></tr><tr><td data-rotulo=\"Função\">Direção</td><td data-rotulo=\"Compromissos específicos\">Decidir com transparência. Aplicar os recursos conforme as regras e prestar contas. Tratar a equipe com igualdade. Proteger alunos e servidores.</td></tr><tr><td data-rotulo=\"Função\">Secretaria escolar</td><td data-rotulo=\"Compromissos específicos\">Guardar documentos e dados com sigilo. Atender com cortesia. Manter os registros fiéis.</td></tr><tr><td data-rotulo=\"Função\">Alimentação escolar</td><td data-rotulo=\"Compromissos específicos\">Seguir o cardápio e as regras de higiene. Zelar pelos alimentos. Atender todos os alunos da mesma forma.</td></tr><tr><td data-rotulo=\"Função\">Limpeza e manutenção</td><td data-rotulo=\"Compromissos específicos\">Zelar pelos espaços e pelos materiais. Comunicar riscos. Respeitar a privacidade em banheiros e vestiários.</td></tr><tr><td data-rotulo=\"Função\">Portaria e vigilância</td><td data-rotulo=\"Compromissos específicos\">Controlar a entrada e a saída. Entregar alunos apenas a pessoas autorizadas. Tratar todos com respeito.</td></tr><tr><td data-rotulo=\"Função\">Cuidadores e apoio à inclusão</td><td data-rotulo=\"Compromissos específicos\">Respeitar a intimidade e a autonomia do aluno. Seguir as orientações da família e da equipe.</td></tr><tr><td data-rotulo=\"Função\">Transporte escolar</td><td data-rotulo=\"Compromissos específicos\">Dirigir com segurança. Cumprir rota e horário. Tratar os alunos com respeito.</td></tr><tr><td data-rotulo=\"Função\">Equipe da Secretaria</td><td data-rotulo=\"Compromissos específicos\">Atender as escolas com agilidade e igualdade. Decidir com base em critérios conhecidos. Proteger os dados da rede.</td></tr></tbody></table></div>"},{"id":"c4","titulo":"Situações do dia a dia","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Conduta adequada</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Um responsável oferece um presente caro.</td><td data-rotulo=\"Conduta adequada\">Agradecer e recusar com gentileza. Lembranças simples podem ser aceitas, conforme as normas da rede.</td></tr><tr><td data-rotulo=\"Situação\">Um colega pede para registrar a presença dele.</td><td data-rotulo=\"Conduta adequada\">Recusar. O registro falso é falta grave para os dois.</td></tr><tr><td data-rotulo=\"Situação\">Um aluno conta algo íntimo da família.</td><td data-rotulo=\"Conduta adequada\">Ouvir, guardar sigilo e, se houver risco, comunicar à direção.</td></tr><tr><td data-rotulo=\"Situação\">Um parente pede vaga fora da regra.</td><td data-rotulo=\"Conduta adequada\">Encaminhar ao procedimento normal, igual para todos.</td></tr><tr><td data-rotulo=\"Situação\">Um fornecedor oferece vantagem.</td><td data-rotulo=\"Conduta adequada\">Recusar e comunicar à direção ou à Secretaria.</td></tr><tr><td data-rotulo=\"Situação\">Alguém publica foto de alunos em rede social pessoal.</td><td data-rotulo=\"Conduta adequada\">Orientar a retirar. Imagens de alunos só nos canais oficiais e com autorização dos responsáveis.</td></tr><tr><td data-rotulo=\"Situação\">Um colega trata um aluno com humilhação.</td><td data-rotulo=\"Conduta adequada\">Intervir com calma para proteger o aluno e comunicar à direção.</td></tr><tr><td data-rotulo=\"Situação\">Você errou em um registro ou decisão.</td><td data-rotulo=\"Conduta adequada\">Comunicar e corrigir. Esconder o erro agrava o problema.</td></tr></tbody></table></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o pedido de um conhecido</div><p><b>Situação.</b> Um conhecido pede a um servidor da secretaria escolar que mude a turma do filho, fora do prazo e sem motivo previsto nas normas.</p><p><b>O que fazer.</b></p><ol><li>Explique com educação que há um procedimento e um prazo iguais para todos.</li><li>Oriente como fazer o pedido pelo caminho normal.</li><li>Se houver insistência, leve à direção.</li></ol><p><b>Resultado esperado.</b> O pedido é tratado como os demais, e a confiança da comunidade na escola é preservada.</p></div>"},{"id":"c5","titulo":"Uso de recursos, tecnologia e redes sociais","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tema</th><th>Conduta</th></tr></thead><tbody><tr><td data-rotulo=\"Tema\">Bens da escola</td><td data-rotulo=\"Conduta\">Uso apenas para o trabalho. Merenda, material e equipamentos pertencem aos alunos e à rede.</td></tr><tr><td data-rotulo=\"Tema\">Tempo de trabalho</td><td data-rotulo=\"Conduta\">Dedicado ao serviço. Assuntos pessoais ficam para os intervalos.</td></tr><tr><td data-rotulo=\"Tema\">Sistemas e senhas</td><td data-rotulo=\"Conduta\">Acesso pessoal e intransferível. Sair da conta em computador compartilhado.</td></tr><tr><td data-rotulo=\"Tema\">Dados de alunos</td><td data-rotulo=\"Conduta\">Usados só para o trabalho. Não saem dos sistemas da rede.</td></tr><tr><td data-rotulo=\"Tema\">Grupos de mensagens</td><td data-rotulo=\"Conduta\">Sem fotos, nomes ou situações de alunos. Sem boatos.</td></tr><tr><td data-rotulo=\"Tema\">Redes sociais pessoais</td><td data-rotulo=\"Conduta\">Sem expor alunos, famílias, colegas ou a escola. Sem falar em nome da rede.</td></tr><tr><td data-rotulo=\"Tema\">Inteligência artificial</td><td data-rotulo=\"Conduta\">Ferramenta de apoio. A decisão sobre o aluno é sempre de uma pessoa.</td></tr></tbody></table></div>"},{"id":"c6","titulo":"Quando algo está errado","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Perceber</b><small>conduta inadequada ou risco</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Proteger</b><small>afastar o aluno do risco</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Comunicar</b><small>à direção ou à Secretaria</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Registrar</b><small>fato, data e quem viu</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Acompanhar</b><small>a apuração é feita por quem tem competência</small></div></div><figcaption>Figura. O que fazer diante de uma conduta inadequada.</figcaption></figure><ul><li>Quem comunica de boa-fé não pode sofrer represália.</li><li>Se a conduta envolve a direção, a comunicação é feita à Secretaria ou à ouvidoria do Município.</li><li>Suspeita de violência contra aluno é comunicada ao Conselho Tutelar, na forma da lei.</li><li>Não cabe ao servidor investigar nem divulgar o caso.</li></ul>"},{"id":"c7","titulo":"Os princípios do serviço público na escola","html":"<p>A Constituição Federal (art. 37) determina que a administração pública obedeça a cinco princípios. Eles valem para o secretário e para quem abre o portão da escola.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>O que significa</th><th>Na escola</th></tr></thead><tbody><tr><td data-rotulo=\"Princípio\">Legalidade</td><td data-rotulo=\"O que significa\">O servidor faz o que a lei determina ou permite.</td><td data-rotulo=\"Na escola\">Seguir o calendário, o regimento e as normas da rede, mesmo quando discorda. A discordância se leva aos canais próprios.</td></tr><tr><td data-rotulo=\"Princípio\">Impessoalidade</td><td data-rotulo=\"O que significa\">Tratar todos igualmente, sem favorecer nem perseguir.</td><td data-rotulo=\"Na escola\">A vaga, o atendimento e a nota não dependem de amizade, parentesco, religião ou política.</td></tr><tr><td data-rotulo=\"Princípio\">Moralidade</td><td data-rotulo=\"O que significa\">Agir com honestidade e boa-fé, além do que a lei exige.</td><td data-rotulo=\"Na escola\">Não tirar proveito do cargo, mesmo quando ninguém está vendo.</td></tr><tr><td data-rotulo=\"Princípio\">Publicidade</td><td data-rotulo=\"O que significa\">Os atos são transparentes.</td><td data-rotulo=\"Na escola\">Regras, gastos e decisões são informados à comunidade. O sigilo protege pessoas, e não a gestão.</td></tr><tr><td data-rotulo=\"Princípio\">Eficiência</td><td data-rotulo=\"O que significa\">Fazer bem feito, com bom uso dos recursos.</td><td data-rotulo=\"Na escola\">Aula preparada, documento no prazo, material cuidado.</td></tr></tbody></table></div><h3>Três perguntas antes de agir</h3><ul><li><b>É legal?</b> Está de acordo com as normas?</li><li><b>É justo?</b> Eu faria o mesmo por qualquer outra pessoa?</li><li><b>Posso explicar?</b> Eu contaria esta decisão, sem constrangimento, à comunidade escolar?</li></ul><p>Se a resposta a qualquer uma for não, pare e procure orientação.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O servidor deve</th><th>O servidor não pode</th></tr></thead><tbody><tr><td data-rotulo=\"O servidor deve\">Comparecer e cumprir o horário.</td><td data-rotulo=\"O servidor não pode\">Ausentar-se sem autorização.</td></tr><tr><td data-rotulo=\"O servidor deve\">Tratar a todos com respeito.</td><td data-rotulo=\"O servidor não pode\">Discriminar, humilhar ou agredir.</td></tr><tr><td data-rotulo=\"O servidor deve\">Guardar sigilo do que conhece pelo cargo.</td><td data-rotulo=\"O servidor não pode\">Divulgar informações de alunos, famílias e colegas.</td></tr><tr><td data-rotulo=\"O servidor deve\">Zelar pelos bens públicos.</td><td data-rotulo=\"O servidor não pode\">Usar bens e serviços da escola para fins particulares.</td></tr><tr><td data-rotulo=\"O servidor deve\">Comunicar irregularidades.</td><td data-rotulo=\"O servidor não pode\">Receber vantagem em razão da função.</td></tr><tr><td data-rotulo=\"O servidor deve\">Cumprir as ordens legais.</td><td data-rotulo=\"O servidor não pode\">Cumprir ordem claramente ilegal.</td></tr><tr><td data-rotulo=\"O servidor deve\">Manter-se atualizado.</td><td data-rotulo=\"O servidor não pode\">Usar o cargo para promoção pessoal, política ou religiosa.</td></tr></tbody></table></div><div class=\"nota\"><b>Estatuto do servidor</b><br/>Os deveres, as proibições e as medidas disciplinares estão no estatuto do servidor do Município e nas normas da rede. Este guia ajuda a compreendê-los, sem substituí-los.</div>"},{"id":"c8","titulo":"A ética de quem ensina","html":"<p>O professor tem um poder grande sobre os alunos: avalia, elogia, corrige e serve de exemplo. A ética docente é o uso cuidadoso desse poder.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Compromisso</th><th>O que significa</th><th>Exemplos de falha</th></tr></thead><tbody><tr><td data-rotulo=\"Compromisso\">Com a aprendizagem de todos</td><td data-rotulo=\"O que significa\">Planejar, ensinar e recuperar, sem desistir de nenhum aluno.</td><td data-rotulo=\"Exemplos de falha\">Dar aula só para quem acompanha. Dizer que um aluno \"não tem jeito\".</td></tr><tr><td data-rotulo=\"Compromisso\">Com o respeito</td><td data-rotulo=\"O que significa\">Tratar o aluno como pessoa em formação.</td><td data-rotulo=\"Exemplos de falha\">Apelidos, ironia, comparação, exposição do erro.</td></tr><tr><td data-rotulo=\"Compromisso\">Com a justiça na avaliação</td><td data-rotulo=\"O que significa\">Avaliar o que foi ensinado, com critérios conhecidos.</td><td data-rotulo=\"Exemplos de falha\">Usar a nota como castigo. Favorecer ou perseguir.</td></tr><tr><td data-rotulo=\"Compromisso\">Com a verdade dos registros</td><td data-rotulo=\"O que significa\">Registrar frequência, conteúdo e notas como de fato ocorreram.</td><td data-rotulo=\"Exemplos de falha\">Lançar presença a quem faltou. Registrar aula não dada.</td></tr><tr><td data-rotulo=\"Compromisso\">Com o tempo da aula</td><td data-rotulo=\"O que significa\">Usar a aula para ensinar.</td><td data-rotulo=\"Exemplos de falha\">Atrasos, uso do celular, assuntos pessoais.</td></tr><tr><td data-rotulo=\"Compromisso\">Com a pluralidade</td><td data-rotulo=\"O que significa\">Apresentar diferentes pontos de vista e respeitar as convicções dos alunos e das famílias.</td><td data-rotulo=\"Exemplos de falha\">Usar a aula para propaganda partidária ou religiosa.</td></tr><tr><td data-rotulo=\"Compromisso\">Com o sigilo</td><td data-rotulo=\"O que significa\">Proteger o que sabe sobre alunos e famílias.</td><td data-rotulo=\"Exemplos de falha\">Comentar casos na sala dos professores ou em grupos.</td></tr><tr><td data-rotulo=\"Compromisso\">Com a própria formação</td><td data-rotulo=\"O que significa\">Estudar e rever a prática.</td><td data-rotulo=\"Exemplos de falha\">Repetir as mesmas aulas por anos, sem olhar os resultados.</td></tr><tr><td data-rotulo=\"Compromisso\">Com a equipe</td><td data-rotulo=\"O que significa\">Colaborar e cumprir os combinados.</td><td data-rotulo=\"Exemplos de falha\">Desautorizar colegas diante de alunos.</td></tr></tbody></table></div><h3>O diário de classe</h3><p>O diário de classe é documento público. O que nele se registra produz efeitos na vida do aluno e na prestação de contas da escola. Registrar informação falsa é falta grave e pode configurar crime.</p><h3>Liberdade de ensinar com responsabilidade</h3><ul><li>A lei garante ao professor a liberdade de ensinar e o pluralismo de ideias.</li><li>Temas controversos podem e devem ser tratados, com base no currículo, em fontes confiáveis e com espaço para posições diferentes.</li><li>O professor pode dizer o que pensa quando perguntado, deixando claro que é uma opinião e que o aluno é livre para pensar diferente.</li><li>O professor não pede voto, não distribui material de campanha e não faz proselitismo religioso.</li><li>A escola pública é laica: respeita todas as crenças e a ausência de crença.</li></ul>"},{"id":"c9","titulo":"A ética de quem dirige e coordena","html":"<p>Quem ocupa cargo de gestão decide sobre pessoas, recursos e informações. A confiança da equipe depende de como essas decisões são tomadas.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>Conduta esperada</th><th>O que evitar</th></tr></thead><tbody><tr><td data-rotulo=\"Área\">Decisões</td><td data-rotulo=\"Conduta esperada\">Critérios claros e iguais para todos. Decisões explicadas.</td><td data-rotulo=\"O que evitar\">Favorecer amigos. Decidir por simpatia.</td></tr><tr><td data-rotulo=\"Área\">Horários e turmas</td><td data-rotulo=\"Conduta esperada\">Distribuição por regras conhecidas.</td><td data-rotulo=\"O que evitar\">Dar as melhores turmas e horários sempre às mesmas pessoas.</td></tr><tr><td data-rotulo=\"Área\">Recursos</td><td data-rotulo=\"Conduta esperada\">Planejar com o conselho, comprar com pesquisa, prestar contas.</td><td data-rotulo=\"O que evitar\">Decidir sozinho. Misturar dinheiro da escola com dinheiro pessoal.</td></tr><tr><td data-rotulo=\"Área\">Informações</td><td data-rotulo=\"Conduta esperada\">Compartilhar o que a equipe precisa saber. Proteger o que é sigiloso.</td><td data-rotulo=\"O que evitar\">Esconder dados ruins. Espalhar assuntos pessoais de servidores.</td></tr><tr><td data-rotulo=\"Área\">Avaliação da equipe</td><td data-rotulo=\"Conduta esperada\">Baseada em fatos, com devolutiva em particular.</td><td data-rotulo=\"O que evitar\">Criticar diante de outros. Avaliar por afinidade.</td></tr><tr><td data-rotulo=\"Área\">Conflitos</td><td data-rotulo=\"Conduta esperada\">Ouvir todos os lados antes de decidir.</td><td data-rotulo=\"O que evitar\">Tomar partido de imediato.</td></tr><tr><td data-rotulo=\"Área\">Queixas das famílias</td><td data-rotulo=\"Conduta esperada\">Receber, apurar e dar retorno.</td><td data-rotulo=\"O que evitar\">Desqualificar a queixa ou expor o servidor antes de ouvi-lo.</td></tr><tr><td data-rotulo=\"Área\">Exemplo</td><td data-rotulo=\"Conduta esperada\">Cumprir horário e regras que cobra dos outros.</td><td data-rotulo=\"O que evitar\">Exigir o que não pratica.</td></tr><tr><td data-rotulo=\"Área\">Relação com a Secretaria</td><td data-rotulo=\"Conduta esperada\">Informar com verdade, inclusive os problemas.</td><td data-rotulo=\"O que evitar\">Maquiar dados para parecer melhor.</td></tr></tbody></table></div><h3>Autoridade sem abuso</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Cobrança legítima</th><th>Abuso</th></tr></thead><tbody><tr><td data-rotulo=\"Cobrança legítima\">Pedir o cumprimento do horário, em particular.</td><td data-rotulo=\"Abuso\">Repreender aos gritos, diante de colegas.</td></tr><tr><td data-rotulo=\"Cobrança legítima\">Exigir o plano de aula no prazo.</td><td data-rotulo=\"Abuso\">Dar tarefas impossíveis para forçar o erro.</td></tr><tr><td data-rotulo=\"Cobrança legítima\">Mudar um horário por necessidade da escola, com explicação.</td><td data-rotulo=\"Abuso\">Mudar horários para punir quem discordou.</td></tr><tr><td data-rotulo=\"Cobrança legítima\">Avaliar o trabalho com critérios conhecidos.</td><td data-rotulo=\"Abuso\">Isolar o servidor, deixar de falar com ele, espalhar boatos.</td></tr></tbody></table></div><div class=\"nota\"><b>Coordenação pedagógica</b><br/>A coordenação acompanha aulas e resultados para apoiar. O que observa em uma sala não é comentado com outros professores, e os dados de uma turma não são usados para constranger quem a ensina.</div>"},{"id":"c10","titulo":"A ética da secretaria escolar","html":"<p>A secretaria escolar lida com documentos que têm valor legal e com informações que as famílias confiam à escola. Exatidão e discrição são as duas virtudes da função.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta correta</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Emissão de histórico ou declaração</td><td data-rotulo=\"Conduta correta\">Emitir apenas com base nos registros. Nunca \"ajustar\" nota, frequência ou data a pedido.</td></tr><tr><td data-rotulo=\"Situação\">Pedido de documento por terceiro</td><td data-rotulo=\"Conduta correta\">Entregar somente ao responsável legal ou a quem tenha autorização por escrito.</td></tr><tr><td data-rotulo=\"Situação\">Pais separados</td><td data-rotulo=\"Conduta correta\">Os dois têm direito a informações sobre o filho, salvo decisão judicial em contrário, arquivada na pasta.</td></tr><tr><td data-rotulo=\"Situação\">Pessoa não autorizada quer retirar o aluno</td><td data-rotulo=\"Conduta correta\">Não liberar. Consultar a ficha e avisar a direção.</td></tr><tr><td data-rotulo=\"Situação\">Ordem de vagas</td><td data-rotulo=\"Conduta correta\">Seguir os critérios da rede. Não guardar vaga, não furar fila.</td></tr><tr><td data-rotulo=\"Situação\">Pedido de \"taxa\" ou contribuição</td><td data-rotulo=\"Conduta correta\">A matrícula e os documentos são sem custo. Nada é condicionado a pagamento ou compra.</td></tr><tr><td data-rotulo=\"Situação\">Erro em documento já emitido</td><td data-rotulo=\"Conduta correta\">Corrigir pelo procedimento oficial, com registro. Não rasurar.</td></tr><tr><td data-rotulo=\"Situação\">Informação sobre família ou aluno</td><td data-rotulo=\"Conduta correta\">Não comentar no balcão, no telefone ou fora da escola.</td></tr><tr><td data-rotulo=\"Situação\">Pedido de um superior para alterar registro</td><td data-rotulo=\"Conduta correta\">Recusar com respeito e comunicar à instância superior.</td></tr><tr><td data-rotulo=\"Situação\">Arquivo</td><td data-rotulo=\"Conduta correta\">Manter organizado e trancado. Não levar documentos para casa.</td></tr></tbody></table></div><h3>No atendimento</h3><ul class=\"chk\"><li><span></span>Cumprimento e escuto até o fim.</li><li><span></span>Uso linguagem simples e confirmo se a pessoa entendeu.</li><li><span></span>Informo documentos e prazos por escrito.</li><li><span></span>Trato com a mesma atenção quem chega bem vestido e quem chega de chinelo.</li><li><span></span>Não comento o caso de uma família diante de outra.</li><li><span></span>Quando não sei, procuro saber e dou retorno.</li></ul><div class=\"nota alerta\"><b>Documento falso é crime</b><br/>Inserir informação falsa em documento público ou alterar um registro verdadeiro são crimes previstos no Código Penal, além de falta funcional grave.</div>"},{"id":"c11","titulo":"A ética de quem cuida do dia a dia","html":"<p>Merendeiras, porteiros, auxiliares de serviços, monitores, motoristas, vigilantes e profissionais de apoio convivem com os alunos tanto quanto os professores. Muitas vezes são os adultos em quem as crianças mais confiam.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Função</th><th>Condutas principais</th></tr></thead><tbody><tr><td data-rotulo=\"Função\">Portaria e vigilância</td><td data-rotulo=\"Condutas principais\">Só liberar alunos a pessoas autorizadas. Identificar visitantes. Não comentar quem entra e sai. Tratar todos os responsáveis com a mesma cortesia. Avisar a direção de qualquer situação estranha.</td></tr><tr><td data-rotulo=\"Função\">Cozinha e alimentação</td><td data-rotulo=\"Condutas principais\">Higiene rigorosa. Servir a todos com igualdade. Respeitar as dietas especiais. Não levar alimentos da escola. Não usar a comida como prêmio ou castigo.</td></tr><tr><td data-rotulo=\"Função\">Limpeza e conservação</td><td data-rotulo=\"Condutas principais\">Guardar produtos fora do alcance dos alunos. Sinalizar piso molhado. Respeitar a privacidade nos banheiros. Avisar a direção sobre riscos e objetos encontrados.</td></tr><tr><td data-rotulo=\"Função\">Apoio em sala e no pátio</td><td data-rotulo=\"Condutas principais\">Seguir as orientações do professor. Cuidar da higiene e da alimentação dos alunos com respeito à intimidade. Não aplicar castigos. Guardar sigilo.</td></tr><tr><td data-rotulo=\"Função\">Transporte escolar</td><td data-rotulo=\"Condutas principais\">Dirigir com prudência. Não transportar pessoas estranhas. Conferir embarque e desembarque. Não deixar aluno sozinho no veículo. Tratar com paciência.</td></tr><tr><td data-rotulo=\"Função\">Apoio administrativo</td><td data-rotulo=\"Condutas principais\">Cuidar de materiais e equipamentos. Não usar recursos para fins pessoais. Guardar sigilo do que lê e ouve.</td></tr></tbody></table></div><h3>Vale para todos</h3><ul><li>Chamar os alunos pelo nome, sem apelidos.</li><li>Não gritar, não ameaçar e não tocar no aluno para corrigir.</li><li>Não ficar a sós com um aluno em local fechado.</li><li>Não fotografar nem filmar alunos.</li><li>Não fazer comentários sobre o corpo, a roupa ou a família dos alunos.</li><li>Não trocar mensagens particulares com alunos.</li><li>Contar à direção, no mesmo dia, qualquer sinal de que um aluno está sofrendo.</li></ul><div class=\"nota\"><b>Todo adulto da escola educa</b><br/>O aluno aprende respeito ao ver como os adultos se tratam e como tratam quem limpa, quem cozinha e quem abre o portão.</div>"},{"id":"c12","titulo":"Limites profissionais com os alunos","html":"<p>Afeto e proximidade fazem parte do trabalho de educar. Os limites existem para proteger o aluno e também o servidor. A regra geral é simples: tudo o que se faz com um aluno deve poder ser feito à vista de outros adultos.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tema</th><th>Conduta adequada</th><th>O que não fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Tema\">Contato físico</td><td data-rotulo=\"Conduta adequada\">Cumprimentos e gestos de cuidado adequados à idade, em público, quando o aluno aceita.</td><td data-rotulo=\"O que não fazer\">Contato que o aluno recusa. Colo e carícias. Contato a sós.</td></tr><tr><td data-rotulo=\"Tema\">Ficar a sós</td><td data-rotulo=\"Conduta adequada\">Conversas individuais em local visível, com a porta aberta.</td><td data-rotulo=\"O que não fazer\">Sala trancada. Encontros fora da escola.</td></tr><tr><td data-rotulo=\"Tema\">Mensagens e redes sociais</td><td data-rotulo=\"Conduta adequada\">Comunicação pelos canais da escola, com os responsáveis.</td><td data-rotulo=\"O que não fazer\">Conversas particulares com alunos. Seguir e ser seguido em perfis pessoais.</td></tr><tr><td data-rotulo=\"Tema\">Presentes</td><td data-rotulo=\"Conduta adequada\">Lembranças simbólicas, coletivas, em datas da escola.</td><td data-rotulo=\"O que não fazer\">Presentes individuais a um aluno. Receber presentes de valor.</td></tr><tr><td data-rotulo=\"Tema\">Caronas</td><td data-rotulo=\"Conduta adequada\">Apenas em emergência, com autorização da direção e dos responsáveis.</td><td data-rotulo=\"O que não fazer\">Transportar alunos no veículo particular por rotina.</td></tr><tr><td data-rotulo=\"Tema\">Segredos</td><td data-rotulo=\"Conduta adequada\">Dizer ao aluno que pode confiar e que você buscará ajuda se ele estiver em risco.</td><td data-rotulo=\"O que não fazer\">Pedir ou prometer segredo.</td></tr><tr><td data-rotulo=\"Tema\">Preferências</td><td data-rotulo=\"Conduta adequada\">Atenção distribuída entre todos.</td><td data-rotulo=\"O que não fazer\">Ter \"queridinhos\". Dar privilégios.</td></tr><tr><td data-rotulo=\"Tema\">Linguagem</td><td data-rotulo=\"Conduta adequada\">Respeitosa e adequada à idade.</td><td data-rotulo=\"O que não fazer\">Piadas de duplo sentido. Comentários sobre aparência. Palavrões.</td></tr><tr><td data-rotulo=\"Tema\">Vida pessoal</td><td data-rotulo=\"Conduta adequada\">Manter reserva.</td><td data-rotulo=\"O que não fazer\">Desabafar com alunos. Pedir favores pessoais.</td></tr><tr><td data-rotulo=\"Tema\">Higiene e troca de roupa</td><td data-rotulo=\"Conduta adequada\">Conforme o combinado com a família e a direção, com outro adulto por perto quando possível.</td><td data-rotulo=\"O que não fazer\">Expor o corpo do aluno. Fotografar.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Relação afetiva ou sexual com aluno</b><br/>Qualquer envolvimento amoroso ou sexual de um adulto da escola com um aluno é violação grave, independentemente da idade ou da vontade declarada do aluno. É comunicado imediatamente à direção, à Secretaria e ao Conselho Tutelar.</div><h3>Se você vir um colega ultrapassar os limites</h3><ol class=\"passos\"><li>Não ignore, mesmo que pareça pequeno.</li><li>Não investigue nem confronte por conta própria.</li><li>Comunique à direção. Se a situação envolver a direção, comunique à Secretaria.</li><li>Registre o que viu, com data e fatos.</li><li>Guarde sigilo.</li></ol><div class=\"nota\"><b>Proteção para quem trabalha direito</b><br/>Limites claros também protegem o servidor de mal-entendidos e de acusações injustas.</div>"},{"id":"c13","titulo":"Respeito entre colegas","html":"<p>A forma como os adultos se tratam define o clima da escola. Discordar faz parte do trabalho. Desrespeitar, não.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Discordo de um colega</td><td data-rotulo=\"Conduta\">Falo com ele, em particular, sobre o fato. Não falo dele com os outros.</td></tr><tr><td data-rotulo=\"Situação\">Ouvi um boato sobre alguém</td><td data-rotulo=\"Conduta\">Não repasso.</td></tr><tr><td data-rotulo=\"Situação\">Um colega errou</td><td data-rotulo=\"Conduta\">Ajudo a corrigir. Se for grave, levo à direção.</td></tr><tr><td data-rotulo=\"Situação\">Um colega novo chegou</td><td data-rotulo=\"Conduta\">Acolho, apresento a escola e me coloco à disposição.</td></tr><tr><td data-rotulo=\"Situação\">Um aluno fala mal de outro professor</td><td data-rotulo=\"Conduta\">Não alimento. Oriento a procurar a coordenação.</td></tr><tr><td data-rotulo=\"Situação\">Tenho uma queixa da direção</td><td data-rotulo=\"Conduta\">Apresento à própria direção. Sem solução, procuro a Secretaria pelos canais oficiais.</td></tr><tr><td data-rotulo=\"Situação\">Sou de outra opinião política ou religiosa</td><td data-rotulo=\"Conduta\">Respeito. A escola não é lugar de disputa.</td></tr></tbody></table></div><h3>Assédio e discriminação</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Conduta</th><th>O que é</th><th>Exemplos</th></tr></thead><tbody><tr><td data-rotulo=\"Conduta\">Assédio moral</td><td data-rotulo=\"O que é\">Humilhar ou constranger alguém de forma repetida, no trabalho.</td><td data-rotulo=\"Exemplos\">Gritar, ridicularizar, isolar, dar tarefas humilhantes, espalhar boatos, ameaçar com frequência.</td></tr><tr><td data-rotulo=\"Conduta\">Assédio sexual</td><td data-rotulo=\"O que é\">Constranger alguém com conduta de natureza sexual não desejada.</td><td data-rotulo=\"Exemplos\">Insinuações, convites insistentes, toques, piadas, mensagens, promessa de vantagem ou ameaça.</td></tr><tr><td data-rotulo=\"Conduta\">Discriminação</td><td data-rotulo=\"O que é\">Tratar pior por cor, origem, religião, sexo, orientação sexual, idade, deficiência ou condição social.</td><td data-rotulo=\"Exemplos\">Piadas, apelidos, exclusão, negar oportunidade.</td></tr></tbody></table></div><ul><li>O assédio sexual é crime previsto no Código Penal. A Lei nº 14.540/2023 instituiu programa de prevenção e enfrentamento ao assédio sexual na administração pública.</li><li>O racismo e a injúria racial são crimes, sem possibilidade de fiança e sem prescrição.</li><li>A vítima não é culpada e não precisa provar sozinha. Ela relata, e o órgão competente apura.</li><li>Quem presencia tem o dever de não se omitir.</li></ul><h3>O que fazer</h3><ol class=\"passos\"><li>Anote datas, locais, o que foi dito ou feito e quem presenciou.</li><li>Guarde mensagens e documentos.</li><li>Procure a direção. Se ela estiver envolvida, procure a Secretaria ou a ouvidoria do Município.</li><li>Busque apoio de saúde e de colegas de confiança.</li><li>Nenhuma retaliação contra quem relata é admitida.</li></ol>"},{"id":"c14","titulo":"Conflito de interesses","html":"<p>Há conflito de interesses quando um ganho pessoal pode influenciar, ou parecer influenciar, uma decisão tomada no trabalho. Evitar a aparência do conflito é tão importante quanto evitar o conflito.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Por que é um problema</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Dar aulas particulares pagas aos próprios alunos</td><td data-rotulo=\"Por que é um problema\">O aluno que paga pode ser favorecido, ou parecer que é.</td><td data-rotulo=\"O que fazer\">Não fazer. Indicar o reforço da escola.</td></tr><tr><td data-rotulo=\"Situação\">Vender produtos a alunos, famílias ou colegas na escola</td><td data-rotulo=\"Por que é um problema\">Usa o local de trabalho e a posição para ganho próprio.</td><td data-rotulo=\"O que fazer\">Não vender no ambiente e no horário de trabalho.</td></tr><tr><td data-rotulo=\"Situação\">Indicar uma empresa de parente para compras da escola</td><td data-rotulo=\"Por que é um problema\">Fere a impessoalidade.</td><td data-rotulo=\"O que fazer\">Declarar o parentesco e não participar da escolha.</td></tr><tr><td data-rotulo=\"Situação\">Receber presente de valor de uma família</td><td data-rotulo=\"Por que é um problema\">Cria obrigação e suspeita.</td><td data-rotulo=\"O que fazer\">Agradecer e recusar. Lembranças simbólicas são aceitáveis.</td></tr><tr><td data-rotulo=\"Situação\">Receber brindes de fornecedor ou de editora</td><td data-rotulo=\"Por que é um problema\">Pode influenciar escolhas de compra e de livros.</td><td data-rotulo=\"O que fazer\">Recusar vantagens pessoais. Comunicar à direção.</td></tr><tr><td data-rotulo=\"Situação\">Avaliar o próprio filho ou parente</td><td data-rotulo=\"Por que é um problema\">Compromete a isenção.</td><td data-rotulo=\"O que fazer\">Informar a direção, que define como proceder.</td></tr><tr><td data-rotulo=\"Situação\">Contratar ou favorecer parentes</td><td data-rotulo=\"Por que é um problema\">O nepotismo é vedado na administração pública.</td><td data-rotulo=\"O que fazer\">Não indicar nem contratar.</td></tr><tr><td data-rotulo=\"Situação\">Usar o cargo para obter vaga, documento ou atendimento fora da regra</td><td data-rotulo=\"Por que é um problema\">Tira o direito de quem estava na fila.</td><td data-rotulo=\"O que fazer\">Seguir os mesmos critérios de todos.</td></tr><tr><td data-rotulo=\"Situação\">Usar dados de famílias para oferecer serviços</td><td data-rotulo=\"Por que é um problema\">Desvia a finalidade dos dados.</td><td data-rotulo=\"O que fazer\">Nunca usar.</td></tr><tr><td data-rotulo=\"Situação\">Fazer campanha eleitoral na escola</td><td data-rotulo=\"Por que é um problema\">Usa a estrutura pública em favor de candidato.</td><td data-rotulo=\"O que fazer\">Não fazer, dentro ou fora do período eleitoral.</td></tr></tbody></table></div><h3>Recursos públicos</h3><ul><li>Material, alimento, equipamento, veículo e tempo de trabalho pertencem ao serviço público.</li><li>Impressões, telefone e internet da escola são para o trabalho.</li><li>Nada é levado para casa sem registro e autorização.</li><li>Dinheiro de eventos, rifas e contribuições voluntárias é administrado pelo conselho escolar, com prestação de contas.</li><li>Nenhuma contribuição é obrigatória, e nenhum aluno é exposto por não contribuir.</li></ul><div class=\"nota alerta\"><b>Improbidade</b><br/>Enriquecer por causa do cargo, causar prejuízo aos cofres públicos de forma intencional e violar de modo doloso os princípios da administração são atos de improbidade, com sanções previstas na Lei nº 8.429/1992.</div>"},{"id":"c15","titulo":"Sigilo, dados e imagem","html":"<p>Na escola, o servidor fica sabendo de notas, diagnósticos, endereços, situações de família e histórias de violência. Essas informações pertencem às pessoas, e não a quem as conhece pelo cargo.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Informação</th><th>Quem pode saber</th><th>Cuidados</th></tr></thead><tbody><tr><td data-rotulo=\"Informação\">Notas e desempenho</td><td data-rotulo=\"Quem pode saber\">O aluno, os responsáveis, os professores do aluno e a gestão.</td><td data-rotulo=\"Cuidados\">Não divulgar listas com nomes. Entregar boletins individualmente.</td></tr><tr><td data-rotulo=\"Informação\">Saúde, deficiência e laudos</td><td data-rotulo=\"Quem pode saber\">Quem atende o aluno e precisa da informação.</td><td data-rotulo=\"Cuidados\">Dados sensíveis. Guardar com acesso restrito.</td></tr><tr><td data-rotulo=\"Informação\">Situação familiar e social</td><td data-rotulo=\"Quem pode saber\">Direção, coordenação e rede de proteção.</td><td data-rotulo=\"Cuidados\">Não comentar com colegas nem com outras famílias.</td></tr><tr><td data-rotulo=\"Informação\">Suspeita de violência</td><td data-rotulo=\"Quem pode saber\">Direção e órgãos de proteção.</td><td data-rotulo=\"Cuidados\">Sigilo absoluto sobre quem comunicou e sobre o caso.</td></tr><tr><td data-rotulo=\"Informação\">Endereço e telefone</td><td data-rotulo=\"Quem pode saber\">Secretaria escolar e gestão.</td><td data-rotulo=\"Cuidados\">Não repassar a terceiros, inclusive a outros responsáveis.</td></tr><tr><td data-rotulo=\"Informação\">Vida funcional dos servidores</td><td data-rotulo=\"Quem pode saber\">Gestão e setor de pessoal.</td><td data-rotulo=\"Cuidados\">Atestados e avaliações são reservados.</td></tr></tbody></table></div><h3>Imagem dos alunos</h3><ul><li>O Estatuto da Criança e do Adolescente protege a imagem, a identidade e a intimidade.</li><li>Fotos e vídeos de alunos só são feitos para fins pedagógicos ou institucionais, com autorização escrita dos responsáveis.</li><li>A divulgação é feita pelos canais oficiais da escola e da Secretaria.</li><li>Servidores não publicam alunos em perfis pessoais.</li><li>Nunca se divulga imagem de aluno em situação constrangedora, de indisciplina, de choro ou de ocorrência.</li><li>O pedido de retirada de uma imagem é atendido de imediato.</li></ul><h3>No dia a dia</h3><ul class=\"chk\"><li><span></span>Não deixo documentos de alunos sobre a mesa ou no balcão.</li><li><span></span>Bloqueio a tela do computador ao sair.</li><li><span></span>Não compartilho a minha senha.</li><li><span></span>Não envio listas e relatórios por aplicativos pessoais.</li><li><span></span>Não falo de alunos no ônibus, no mercado ou em redes sociais.</li><li><span></span>Descarto papéis com dados pessoais de forma segura.</li><li><span></span>Comunico à direção qualquer perda ou vazamento de dados.</li></ul><div class=\"nota\"><b>Quando o sigilo cede</b><br/>O sigilo não impede a comunicação obrigatória. Diante de suspeita de violência contra criança ou adolescente, comunicar ao Conselho Tutelar é dever, feito pela direção e de forma reservada.</div>"},{"id":"c16","titulo":"O servidor nas redes sociais","html":"<p>O que o servidor publica na vida pessoal é direito dele. Mas a comunidade o reconhece como alguém da escola, dentro e fora do horário. Algumas cautelas protegem a pessoa e a instituição.</p><div class=\"tb\"><table><thead><tr><th>Pode</th><th>Evite</th><th>Não pode</th></tr></thead><tbody><tr><td data-rotulo=\"Pode\">Ter perfis pessoais e opinar como cidadão.</td><td data-rotulo=\"Evite\">Aceitar alunos e responsáveis em perfis pessoais.</td><td data-rotulo=\"Não pode\">Publicar imagens e dados de alunos.</td></tr><tr><td data-rotulo=\"Pode\">Divulgar eventos públicos da escola, compartilhando dos canais oficiais.</td><td data-rotulo=\"Evite\">Discutir com responsáveis em comentários.</td><td data-rotulo=\"Não pode\">Expor colegas, famílias ou casos da escola.</td></tr><tr><td data-rotulo=\"Pode\">Participar de grupos profissionais.</td><td data-rotulo=\"Evite\">Publicar durante o horário de aula.</td><td data-rotulo=\"Não pode\">Ofender, discriminar ou ameaçar.</td></tr><tr><td data-rotulo=\"Pode\">Manifestar-se sobre educação.</td><td data-rotulo=\"Evite\">Falar em nome da escola sem autorização.</td><td data-rotulo=\"Não pode\">Divulgar informações sigilosas ou documentos internos.</td></tr></tbody></table></div><h3>Grupos de mensagens com responsáveis</h3><ul><li>São criados e administrados conforme a orientação da escola.</li><li>Servem para avisos gerais, em horário combinado.</li><li>Assuntos de um aluno são tratados em particular, pelos canais oficiais.</li><li>Não se publicam fotos, notas, listas de pendências ou ocorrências.</li><li>Mensagens ofensivas são tratadas pela direção.</li></ul><h3>Período eleitoral</h3><p>A legislação eleitoral proíbe o uso de bens, serviços e servidores públicos em favor de candidatos. Na escola:</p><ul><li>Não se distribui nem se afixa material de campanha.</li><li>Não se usam reuniões, eventos e canais da escola para pedir votos.</li><li>Não se usam roupas e adereços de campanha no trabalho.</li><li>O servidor não é obrigado a participar de atos políticos e não pode constranger ninguém a fazê-lo.</li><li>A cessão do prédio segue as regras da Justiça Eleitoral e da Secretaria.</li></ul><div class=\"nota\"><b>Pense antes de publicar</b><br/>Uma boa pergunta: eu diria isto, deste modo, em uma reunião com os responsáveis? Se a resposta for não, é melhor não publicar.</div>"},{"id":"c17","titulo":"Como decidir diante de um dilema","html":"<p>Nem toda situação tem resposta pronta nas normas. Um dilema ético aparece quando dois valores entram em choque: a lealdade a um colega e a proteção de um aluno, a regra e a compaixão, o sigilo e a transparência.</p><ol class=\"passos\"><li><b>Pare.</b> Não decida no impulso nem sob pressão.</li><li><b>Descreva os fatos.</b> O que eu sei? O que estou supondo?</li><li><b>Identifique quem é afetado.</b> Em especial, o aluno.</li><li><b>Consulte as normas.</b> O que dizem a lei, o regimento e as orientações da rede?</li><li><b>Liste as opções.</b> Quase sempre há mais de duas.</li><li><b>Teste cada opção.</b> É legal? É justa? Eu poderia explicá-la em público? Protege o mais vulnerável?</li><li><b>Peça orientação.</b> À direção, à coordenação ou à Secretaria.</li><li><b>Decida e registre.</b> Anote o que foi decidido e por quê.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Quando houver choque entre</th><th>Prevalece, em geral</th></tr></thead><tbody><tr><td data-rotulo=\"Quando houver choque entre\">O interesse do aluno e a conveniência do adulto</td><td data-rotulo=\"Prevalece, em geral\">O interesse do aluno.</td></tr><tr><td data-rotulo=\"Quando houver choque entre\">A proteção de uma criança e a lealdade a um colega</td><td data-rotulo=\"Prevalece, em geral\">A proteção da criança.</td></tr><tr><td data-rotulo=\"Quando houver choque entre\">O sigilo e o dever legal de comunicar violência</td><td data-rotulo=\"Prevalece, em geral\">O dever de comunicar, de forma reservada.</td></tr><tr><td data-rotulo=\"Quando houver choque entre\">A ordem de um superior e a lei</td><td data-rotulo=\"Prevalece, em geral\">A lei.</td></tr><tr><td data-rotulo=\"Quando houver choque entre\">A regra e uma situação excepcional</td><td data-rotulo=\"Prevalece, em geral\">A regra, com consulta à instância superior sobre a exceção.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · pense em um dilema</div><div class=\"q\"><b>1.</b> Descreva um dilema que você já viveu no trabalho, sem citar nomes.<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que valores estavam em choque?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Usando os passos acima, você decidiria do mesmo modo?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c18","titulo":"Canais, apuração e garantias","html":"<p>Uma rede ética precisa de caminhos claros para que os problemas sejam relatados, apurados e resolvidos, com proteção para quem relata e direito de defesa para quem é citado.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>A quem levar</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Dúvida sobre como agir</td><td data-rotulo=\"A quem levar\">Direção ou coordenação.</td></tr><tr><td data-rotulo=\"Situação\">Conduta inadequada de um colega</td><td data-rotulo=\"A quem levar\">Direção.</td></tr><tr><td data-rotulo=\"Situação\">Conduta inadequada da direção</td><td data-rotulo=\"A quem levar\">Secretaria de Educação.</td></tr><tr><td data-rotulo=\"Situação\">Irregularidade com recursos</td><td data-rotulo=\"A quem levar\">Direção, conselho escolar, Secretaria e órgãos de controle.</td></tr><tr><td data-rotulo=\"Situação\">Assédio ou discriminação</td><td data-rotulo=\"A quem levar\">Direção, Secretaria ou ouvidoria do Município.</td></tr><tr><td data-rotulo=\"Situação\">Suspeita de violência contra aluno</td><td data-rotulo=\"A quem levar\">Direção, que comunica ao Conselho Tutelar. Em omissão, o servidor comunica diretamente.</td></tr><tr><td data-rotulo=\"Situação\">Vazamento de dados</td><td data-rotulo=\"A quem levar\">Direção e encarregado de dados do Município.</td></tr><tr><td data-rotulo=\"Situação\">Risco imediato à vida</td><td data-rotulo=\"A quem levar\">Telefones 190 e 192.</td></tr></tbody></table></div><h3>Como relatar</h3><ul><li>Descreva fatos: o que, quando, onde, quem presenciou.</li><li>Junte o que tiver: mensagens, documentos, datas.</li><li>Não acrescente opiniões nem suposições.</li><li>Use o canal oficial, por escrito, e guarde o comprovante.</li><li>Mantenha reserva enquanto o caso é apurado.</li></ul><h3>Garantias</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Para quem relata</th><th>Para quem é citado</th></tr></thead><tbody><tr><td data-rotulo=\"Para quem relata\">Sigilo da identidade, quando solicitado e possível.</td><td data-rotulo=\"Para quem é citado\">Presunção de inocência até a conclusão.</td></tr><tr><td data-rotulo=\"Para quem relata\">Proteção contra retaliação.</td><td data-rotulo=\"Para quem é citado\">Conhecimento do que lhe é atribuído.</td></tr><tr><td data-rotulo=\"Para quem relata\">Informação sobre o andamento, dentro do que o sigilo permite.</td><td data-rotulo=\"Para quem é citado\">Direito de se defender e de apresentar provas.</td></tr><tr><td data-rotulo=\"Para quem relata\">Apoio da gestão.</td><td data-rotulo=\"Para quem é citado\">Tratamento respeitoso e reserva sobre o caso.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Relato de má-fé</b><br/>Acusar alguém sabendo que é inocente também é falta grave. O relato responsável se baseia em fatos.</div><div class=\"nota\"><b>Apurar não é punir</b><br/>A apuração existe para esclarecer. As medidas disciplinares seguem o estatuto do servidor, com processo regular e direito de defesa.</div>"},{"id":"c19","titulo":"Tecnologia e inteligência artificial com ética","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tema</th><th>Conduta</th></tr></thead><tbody><tr><td data-rotulo=\"Tema\">Senhas e acessos</td><td data-rotulo=\"Conduta\">Pessoais e intransferíveis. Cada um responde pelo que é feito com o próprio acesso.</td></tr><tr><td data-rotulo=\"Tema\">Equipamentos da escola</td><td data-rotulo=\"Conduta\">Uso para o trabalho. Cuidado, registro de entrega e devolução.</td></tr><tr><td data-rotulo=\"Tema\">Sistemas com dados de alunos</td><td data-rotulo=\"Conduta\">Acessar apenas o necessário à função. Não exportar nem fotografar telas para compartilhar.</td></tr><tr><td data-rotulo=\"Tema\">Plataforma de reforço escolar</td><td data-rotulo=\"Conduta\">Usar os dados para apoiar o aluno. Não fazer ranking nem expor resultados.</td></tr><tr><td data-rotulo=\"Tema\">Ferramentas de inteligência artificial</td><td data-rotulo=\"Conduta\">Não inserir nomes, dados pessoais ou relatos de alunos em ferramentas não autorizadas pela rede. Conferir o que a ferramenta produz antes de usar.</td></tr><tr><td data-rotulo=\"Tema\">Materiais de terceiros</td><td data-rotulo=\"Conduta\">Respeitar os direitos autorais. Citar as fontes.</td></tr><tr><td data-rotulo=\"Tema\">Gravação de aulas e reuniões</td><td data-rotulo=\"Conduta\">Apenas com conhecimento de todos e para fim definido.</td></tr><tr><td data-rotulo=\"Tema\">Celular no trabalho</td><td data-rotulo=\"Conduta\">Uso moderado, fora dos momentos de atendimento e de aula.</td></tr></tbody></table></div><h3>Honestidade intelectual</h3><ul><li>O professor ensina a pesquisar, a citar e a reconhecer o trabalho dos outros.</li><li>Planos, relatórios e projetos são de quem os fez. Copiar o trabalho de um colega sem crédito é falta.</li><li>O uso de inteligência artificial em atividades é combinado com os alunos, com regras claras do que é permitido.</li><li>A avaliação considera o processo, e não apenas o produto final.</li></ul><div class=\"nota\"><b>A ferramenta não decide</b><br/>Sistemas e ferramentas apoiam o trabalho. A responsabilidade pelas decisões sobre os alunos continua sendo das pessoas.</div>"},{"id":"c20","titulo":"Mais situações para discutir","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · o pedido da amiga</div><p><b>Situação.</b> Uma servidora da secretaria escolar recebe o pedido de uma amiga para \"arrumar\" uma vaga na turma da manhã, que está completa.</p><p><b>O que fazer.</b></p><ol><li>Explicar que as vagas seguem critérios iguais para todos.</li><li>Orientar sobre o procedimento e a lista de espera.</li><li>Não registrar nenhuma reserva informal.</li><li>Se houver insistência, informar a direção.</li></ol><p><b>Resultado esperado.</b> A amizade é preservada, e ninguém perde a vez na fila.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a foto no perfil pessoal</div><p><b>Situação.</b> Uma professora publica no próprio perfil a foto da turma na festa junina. Uma mãe pede a retirada.</p><p><b>O que fazer.</b></p><ol><li>Retirar a imagem de imediato e desculpar-se.</li><li>Passar a enviar fotos apenas à coordenação, para divulgação nos canais oficiais.</li><li>Verificar as autorizações de imagem da turma.</li><li>A direção relembra a regra a toda a equipe.</li></ol><p><b>Resultado esperado.</b> A família é atendida, e a escola reforça o cuidado com a imagem dos alunos.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o diário preenchido depois</div><p><b>Situação.</b> Um professor não registrou a frequência por três semanas e pretende lançar presença para todos.</p><p><b>O que fazer.</b></p><ol><li>Não lançar informação que não corresponde à realidade.</li><li>Procurar a coordenação e relatar a falha.</li><li>Reconstituir a frequência com base em atividades e outros registros, conforme a orientação da direção.</li><li>Passar a registrar no mesmo dia.</li></ol><p><b>Resultado esperado.</b> O registro reflete o que ocorreu, e os alunos faltosos entram na busca ativa.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o presente do fornecedor</div><p><b>Situação.</b> Um vendedor oferece à diretora um aparelho eletrônico \"de cortesia\" depois de uma compra da escola.</p><p><b>O que fazer.</b></p><ol><li>Recusar e agradecer.</li><li>Informar que a escola não aceita vantagens pessoais.</li><li>Registrar o fato e comunicar à Secretaria.</li><li>Manter a pesquisa de preços com vários fornecedores nas compras seguintes.</li></ol><p><b>Resultado esperado.</b> A escolha de fornecedores continua baseada em preço e qualidade.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a brincadeira na sala dos professores</div><p><b>Situação.</b> Um professor faz, com frequência, piadas sobre a aparência de uma colega. Os outros riem. Ela se cala.</p><p><b>O que fazer.</b></p><ol><li>Quem presencia não ri e diz que a piada não tem graça.</li><li>Um colega pergunta a ela, em particular, como está e oferece apoio.</li><li>A situação é levada à direção.</li><li>A direção conversa com o autor e registra. Havendo repetição, encaminha para apuração.</li></ol><p><b>Resultado esperado.</b> O ambiente deixa de tolerar a conduta, e a colega se sente amparada.</p></div>"},{"id":"c21","titulo":"Respeito à diversidade","html":"<p>A escola pública recebe crianças e famílias de todas as origens, crenças e condições. Tratar a todos com igual respeito é dever legal e parte do que a escola ensina.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dimensão</th><th>O que a lei e as normas estabelecem</th><th>Conduta do servidor</th></tr></thead><tbody><tr><td data-rotulo=\"Dimensão\">Cor, raça e origem</td><td data-rotulo=\"O que a lei e as normas estabelecem\">Racismo e injúria racial são crimes. O ensino da história e da cultura afro-brasileira e indígena é obrigatório.</td><td data-rotulo=\"Conduta do servidor\">Não fazer nem tolerar piadas, apelidos e comparações. Intervir quando presenciar.</td></tr><tr><td data-rotulo=\"Dimensão\">Religião</td><td data-rotulo=\"O que a lei e as normas estabelecem\">O Estado é laico. A liberdade de crença e de não ter crença é garantida.</td><td data-rotulo=\"Conduta do servidor\">Não promover nem desqualificar religiões. Respeitar símbolos e práticas dos alunos.</td></tr><tr><td data-rotulo=\"Dimensão\">Deficiência</td><td data-rotulo=\"O que a lei e as normas estabelecem\">A recusa de matrícula e a discriminação são vedadas. O aluno tem direito a adaptações.</td><td data-rotulo=\"Conduta do servidor\">Falar com o aluno, e não só com o acompanhante. Garantir a participação.</td></tr><tr><td data-rotulo=\"Dimensão\">Gênero e orientação sexual</td><td data-rotulo=\"O que a lei e as normas estabelecem\">Ninguém pode ser discriminado.</td><td data-rotulo=\"Conduta do servidor\">Tratar com respeito, usar o nome pelo qual a pessoa pede para ser chamada conforme as normas da rede, não tolerar ofensas.</td></tr><tr><td data-rotulo=\"Dimensão\">Condição social</td><td data-rotulo=\"O que a lei e as normas estabelecem\">A educação é direito de todos.</td><td data-rotulo=\"Conduta do servidor\">Não expor quem não tem material, uniforme ou dinheiro para contribuições.</td></tr><tr><td data-rotulo=\"Dimensão\">Origem regional e migrantes</td><td data-rotulo=\"O que a lei e as normas estabelecem\">Matrícula garantida, mesmo sem documentação completa.</td><td data-rotulo=\"Conduta do servidor\">Acolher o sotaque, a língua e os costumes.</td></tr><tr><td data-rotulo=\"Dimensão\">Configuração familiar</td><td data-rotulo=\"O que a lei e as normas estabelecem\">Toda família merece o mesmo respeito.</td><td data-rotulo=\"Conduta do servidor\">Usar \"responsáveis\". Adaptar atividades de datas comemorativas.</td></tr></tbody></table></div><h3>Diante de uma fala discriminatória</h3><ol class=\"passos\"><li>Interrompa na hora, com calma: \"Aqui não falamos assim de ninguém.\"</li><li>Acolha quem foi atingido, em particular.</li><li>Converse com quem falou, explicando o dano e a regra.</li><li>Registre e comunique à direção.</li><li>Trabalhe o tema com a turma, sem expor os envolvidos.</li></ol><div class=\"nota alerta\"><b>Omissão também ensina</b><br/>Quando um adulto ouve uma ofensa e se cala, os alunos entendem que ela é aceita.</div>"},{"id":"c22","titulo":"Compromisso com o tempo e com a presença","html":"<p>O tempo de aula é o recurso mais escasso da escola. Cada atraso e cada ausência do adulto tiram do aluno algo que não volta.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Efeito sobre os alunos</th><th>Conduta esperada</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Chegar depois do horário</td><td data-rotulo=\"Efeito sobre os alunos\">Turma sem adulto, aula mais curta, mau exemplo.</td><td data-rotulo=\"Conduta esperada\">Chegar antes da turma. Em imprevisto, avisar a direção o quanto antes.</td></tr><tr><td data-rotulo=\"Situação\">Faltar sem avisar</td><td data-rotulo=\"Efeito sobre os alunos\">A escola não consegue organizar a substituição.</td><td data-rotulo=\"Conduta esperada\">Avisar com a maior antecedência possível e deixar atividades.</td></tr><tr><td data-rotulo=\"Situação\">Sair antes do fim</td><td data-rotulo=\"Efeito sobre os alunos\">Alunos sem supervisão.</td><td data-rotulo=\"Conduta esperada\">Cumprir o horário até o último minuto.</td></tr><tr><td data-rotulo=\"Situação\">Usar a aula para assuntos pessoais</td><td data-rotulo=\"Efeito sobre os alunos\">Tempo de ensino perdido.</td><td data-rotulo=\"Conduta esperada\">Celular guardado. Assuntos pessoais no intervalo.</td></tr><tr><td data-rotulo=\"Situação\">Liberar a turma mais cedo</td><td data-rotulo=\"Efeito sobre os alunos\">Alunos na rua sem que a família saiba.</td><td data-rotulo=\"Conduta esperada\">Nunca liberar sem autorização da direção.</td></tr><tr><td data-rotulo=\"Situação\">Entregar documentos fora do prazo</td><td data-rotulo=\"Efeito sobre os alunos\">Atraso em boletins, transferências e conselhos.</td><td data-rotulo=\"Conduta esperada\">Organizar-se e avisar quando houver dificuldade.</td></tr></tbody></table></div><h3>Quando o servidor precisa se ausentar</h3><ul><li>Os afastamentos previstos em lei são direitos e seguem o procedimento do Município.</li><li>O atestado é entregue no prazo e tratado com sigilo.</li><li>Sempre que possível, o professor deixa o plano e as atividades da turma.</li><li>Na volta, informa-se do que foi trabalhado na ausência.</li><li>Nenhum servidor deve ser constrangido por usar um direito.</li></ul><h3>Zelo pelo trabalho</h3><ul class=\"chk\"><li><span></span>Preparo as aulas ou as tarefas do dia com antecedência.</li><li><span></span>Cumpro os prazos de registros e documentos.</li><li><span></span>Mantenho o meu espaço de trabalho organizado.</li><li><span></span>Participo das reuniões e das formações.</li><li><span></span>Aviso quando não vou conseguir cumprir algo.</li><li><span></span>Deixo as informações organizadas para quem me substitui.</li></ul><div class=\"nota\"><b>Pontualidade é respeito</b><br/>Chegar na hora diz ao aluno que ele é importante. Ele aprende isso antes de aprender qualquer conteúdo.</div>"},{"id":"c23","titulo":"Eventos, contribuições e parcerias","html":"<p>Festas, formaturas, rifas, passeios e parcerias movimentam dinheiro e expõem alunos. Regras claras evitam constrangimentos e suspeitas.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Regra</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Contribuição voluntária</td><td data-rotulo=\"Regra\">É voluntária de fato. Não há lista de quem pagou, cobrança por bilhete ao aluno nem tratamento diferente.</td></tr><tr><td data-rotulo=\"Situação\">Rifa, bazar e festa</td><td data-rotulo=\"Regra\">Decididos com o conselho escolar. Dinheiro recebido com registro e prestação de contas à comunidade.</td></tr><tr><td data-rotulo=\"Situação\">Passeio pago</td><td data-rotulo=\"Regra\">Nenhum aluno fica de fora por não poder pagar. A escola busca alternativa.</td></tr><tr><td data-rotulo=\"Situação\">Formatura</td><td data-rotulo=\"Regra\">Sem obrigação de compra de fotos, roupas ou pacotes. A cerimônia da escola é para todos.</td></tr><tr><td data-rotulo=\"Situação\">Uniforme e material</td><td data-rotulo=\"Regra\">A falta não impede a entrada nem a participação. A escola busca solução com a família e a rede.</td></tr><tr><td data-rotulo=\"Situação\">Venda de alimentos e produtos</td><td data-rotulo=\"Regra\">Conforme as normas da rede. Servidores não vendem para proveito próprio.</td></tr><tr><td data-rotulo=\"Situação\">Fotógrafos e empresas</td><td data-rotulo=\"Regra\">Entram com autorização da direção. Imagens de alunos só com autorização dos responsáveis.</td></tr><tr><td data-rotulo=\"Situação\">Doações</td><td data-rotulo=\"Regra\">Recebidas pelos meios oficiais, com registro. Não geram favorecimento ao doador.</td></tr><tr><td data-rotulo=\"Situação\">Parcerias com empresas e entidades</td><td data-rotulo=\"Regra\">Formalizadas pela Secretaria. Sem propaganda dirigida aos alunos e sem acesso a dados pessoais.</td></tr><tr><td data-rotulo=\"Situação\">Presença de autoridades e candidatos</td><td data-rotulo=\"Regra\">Segue as regras da Secretaria e, em período eleitoral, da Justiça Eleitoral.</td></tr></tbody></table></div><h3>Três perguntas antes de organizar um evento</h3><ul><li>Todos os alunos poderão participar, tenham ou não dinheiro?</li><li>O dinheiro terá registro e prestação de contas?</li><li>Algum aluno ou família pode se sentir exposto?</li></ul><div class=\"nota alerta\"><b>Nunca pelo aluno</b><br/>Cobranças, lembretes de pagamento e pendências não são entregues ao aluno nem ditos diante da turma. A conversa é com o responsável, em particular.</div>"},{"id":"c24","titulo":"Estagiários, voluntários e terceirizados","html":"<p>Além dos servidores, circulam na escola estagiários, voluntários, monitores de programas, prestadores de serviço e funcionários de empresas contratadas. Todos convivem com alunos e seguem as mesmas regras de conduta.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quem</th><th>Cuidados da direção</th></tr></thead><tbody><tr><td data-rotulo=\"Quem\">Estagiários</td><td data-rotulo=\"Cuidados da direção\">Termo de estágio regular. Atuam sempre com um professor ou servidor responsável. Não ficam sozinhos com turmas.</td></tr><tr><td data-rotulo=\"Quem\">Voluntários</td><td data-rotulo=\"Cuidados da direção\">Termo de adesão ao serviço voluntário. Atividade definida e acompanhada. Identificação visível.</td></tr><tr><td data-rotulo=\"Quem\">Monitores de programas</td><td data-rotulo=\"Cuidados da direção\">Orientação sobre as regras da escola e a proteção dos alunos.</td></tr><tr><td data-rotulo=\"Quem\">Empresas contratadas</td><td data-rotulo=\"Cuidados da direção\">Funcionários identificados. Reclamações encaminhadas ao fiscal do contrato.</td></tr><tr><td data-rotulo=\"Quem\">Prestadores eventuais</td><td data-rotulo=\"Cuidados da direção\">Entrada registrada. Serviço feito, de preferência, fora do horário de aula. Acompanhados por servidor.</td></tr><tr><td data-rotulo=\"Quem\">Visitantes e palestrantes</td><td data-rotulo=\"Cuidados da direção\">Convite aprovado pela direção. Conteúdo conhecido antes. Professor presente durante a atividade.</td></tr></tbody></table></div><h3>O que todos recebem ao chegar</h3><ul class=\"chk\"><li><span></span>As regras de conduta com alunos: sem contato a sós, sem fotos, sem redes sociais.</li><li><span></span>A orientação de sigilo.</li><li><span></span>O nome de quem procurar em caso de dúvida ou de situação preocupante.</li><li><span></span>A identificação a usar na escola.</li><li><span></span>A informação sobre o plano de segurança.</li></ul><div class=\"nota\"><b>Antecedentes</b><br/>A lei exige de quem trabalha com crianças e adolescentes a apresentação periódica de certidões de antecedentes criminais. A Secretaria orienta como isso é feito na rede.</div><h3>Como o servidor se relaciona com eles</h3><ul><li>Com o mesmo respeito devido a qualquer colega.</li><li>Orientando, quando presenciar algo inadequado, e comunicando à direção.</li><li>Sem delegar tarefas que são do servidor, como ficar com a turma ou acessar dados de alunos.</li></ul>"},{"id":"c25","titulo":"Reconhecer e reparar um erro","html":"<p>Todo profissional erra. O que diferencia uma conduta ética é o que se faz depois. Esconder o erro costuma causar mais dano do que o erro em si.</p><ol class=\"passos\"><li><b>Reconheça</b>, sem justificativas longas.</li><li><b>Comunique</b> a quem precisa saber: a pessoa atingida e a chefia.</li><li><b>Repare</b> o que for possível.</li><li><b>Aprenda:</b> o que mudar para não repetir.</li><li><b>Siga em frente</b>, sem se punir além do necessário.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Erro</th><th>Como reparar</th></tr></thead><tbody><tr><td data-rotulo=\"Erro\">Gritei com um aluno diante da turma.</td><td data-rotulo=\"Como reparar\">Pedir desculpas ao aluno e à turma. Conversar com a coordenação sobre o que aconteceu.</td></tr><tr><td data-rotulo=\"Erro\">Lancei uma nota errada.</td><td data-rotulo=\"Como reparar\">Avisar a secretaria escolar e corrigir pelo procedimento oficial. Informar o aluno e a família.</td></tr><tr><td data-rotulo=\"Erro\">Comentei um caso de aluno em um grupo.</td><td data-rotulo=\"Como reparar\">Apagar, avisar a direção e não repetir.</td></tr><tr><td data-rotulo=\"Erro\">Esqueci de comunicar uma falta prolongada.</td><td data-rotulo=\"Como reparar\">Comunicar de imediato e ajudar na busca ativa.</td></tr><tr><td data-rotulo=\"Erro\">Tratei mal um responsável.</td><td data-rotulo=\"Como reparar\">Procurar a pessoa, pedir desculpas e retomar a conversa.</td></tr><tr><td data-rotulo=\"Erro\">Perdi um documento.</td><td data-rotulo=\"Como reparar\">Comunicar à direção no mesmo dia.</td></tr><tr><td data-rotulo=\"Erro\">Fui injusto com um colega.</td><td data-rotulo=\"Como reparar\">Conversar em particular e reconhecer.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · pedindo desculpas a um aluno</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Ontem eu levantei a voz com você na frente da turma. Eu errei. Peço desculpas.</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Tudo bem.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">O que você fez também não foi certo, e vamos conversar sobre isso. Mas a minha reação não foi a de um professor. Não vai se repetir.</div></div></div><div class=\"nota\"><b>O que o aluno aprende</b><br/>Um adulto que reconhece o erro ensina ao aluno que errar não diminui ninguém e que reparar é possível.</div><h3>Quando o erro é de outro</h3><ul><li>Fale primeiro com a pessoa, em particular, quando o erro for pequeno.</li><li>Leve à direção quando houver prejuízo a alunos ou ao serviço.</li><li>Não espalhe.</li><li>Não use o erro do colega para se promover.</li></ul>"},{"id":"c26","titulo":"Perguntas frequentes","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td data-rotulo=\"Pergunta\">Posso aceitar um bolo ou uma lembrança de uma família?</td><td data-rotulo=\"Resposta\">Lembranças simbólicas, oferecidas de forma espontânea, podem ser aceitas. Presentes de valor, não.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso ter alunos nas minhas redes sociais?</td><td data-rotulo=\"Resposta\">Não é recomendado. A comunicação é pelos canais da escola, com os responsáveis.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso dar carona a um aluno?</td><td data-rotulo=\"Resposta\">Apenas em emergência, com autorização da direção e dos responsáveis.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso dar aula particular a alunos de outra escola?</td><td data-rotulo=\"Resposta\">Fora do horário de trabalho e sem usar a estrutura pública, sim. Aos próprios alunos, não.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso falar de política em sala?</td><td data-rotulo=\"Resposta\">O tema pode ser tratado de forma pedagógica e plural. Pedir voto e fazer propaganda, não.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso rezar com a turma?</td><td data-rotulo=\"Resposta\">A escola pública é laica. Práticas religiosas não são conduzidas pelo servidor.</td></tr><tr><td data-rotulo=\"Pergunta\">Um colega me pediu para assinar o ponto por ele.</td><td data-rotulo=\"Resposta\">Não assine. É registro falso.</td></tr><tr><td data-rotulo=\"Pergunta\">A direção me pediu para alterar uma nota.</td><td data-rotulo=\"Resposta\">Notas só são alteradas pelo professor, pelo procedimento oficial, quando há erro. Recuse e procure a Secretaria.</td></tr><tr><td data-rotulo=\"Pergunta\">Soube de algo grave por um aluno, que pediu segredo.</td><td data-rotulo=\"Resposta\">Se envolve risco ou violência, o sigilo cede ao dever de proteger. Comunique à direção.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso filmar um aluno em crise para mostrar à família?</td><td data-rotulo=\"Resposta\">Não. Descreva por escrito o que ocorreu.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso levar um equipamento da escola para casa?</td><td data-rotulo=\"Resposta\">Somente com autorização e registro.</td></tr><tr><td data-rotulo=\"Pergunta\">Não concordo com uma norma da rede.</td><td data-rotulo=\"Resposta\">Cumpra e leve a sua discordância aos canais próprios.</td></tr><tr><td data-rotulo=\"Pergunta\">Um responsável me ofendeu.</td><td data-rotulo=\"Resposta\">Não responda. Encaminhe à direção e registre.</td></tr><tr><td data-rotulo=\"Pergunta\">Fui acusado injustamente.</td><td data-rotulo=\"Resposta\">Peça para ser ouvido, apresente os fatos e confie no procedimento. Você tem direito de defesa.</td></tr></tbody></table></div>"},{"id":"c27","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td data-rotulo=\"Encontro\">1</td><td data-rotulo=\"Capítulos\">Do início até \"Os princípios do serviço público\"</td><td data-rotulo=\"Perguntas para a conversa\">Qual dos cinco princípios é mais difícil de praticar na escola? Por quê?</td></tr><tr><td data-rotulo=\"Encontro\">2</td><td data-rotulo=\"Capítulos\">Capítulos sobre a ética de cada função</td><td data-rotulo=\"Perguntas para a conversa\">O que cada função espera das outras? Onde há atrito?</td></tr><tr><td data-rotulo=\"Encontro\">3</td><td data-rotulo=\"Capítulos\">\"Limites profissionais\" e \"Respeito entre colegas\"</td><td data-rotulo=\"Perguntas para a conversa\">Os nossos limites com os alunos estão claros para todos? Como reagimos a uma piada ofensiva?</td></tr><tr><td data-rotulo=\"Encontro\">4</td><td data-rotulo=\"Capítulos\">\"Conflito de interesses\", \"Sigilo\" e \"Redes sociais\"</td><td data-rotulo=\"Perguntas para a conversa\">Que situação de conflito de interesses já apareceu aqui? Como tratamos imagens de alunos?</td></tr><tr><td data-rotulo=\"Encontro\">5</td><td data-rotulo=\"Capítulos\">Dos dilemas até o final</td><td data-rotulo=\"Perguntas para a conversa\">Discussão de três casos do guia e assinatura do termo de compromisso.</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c28","titulo":"O meu compromisso","html":"<p>Ética se pratica nas pequenas escolhas de todos os dias. Use esta página para pensar na sua própria função.</p><ul class=\"chk\"><li><span></span>Cumpro o meu horário e as minhas tarefas.</li><li><span></span>Trato alunos, famílias e colegas com respeito, sem distinção.</li><li><span></span>Não uso o cargo, o tempo ou os bens da escola em proveito próprio.</li><li><span></span>Registro e informo apenas o que é verdadeiro.</li><li><span></span>Guardo sigilo sobre o que sei pelo trabalho.</li><li><span></span>Mantenho limites profissionais com os alunos.</li><li><span></span>Não publico imagens nem informações de alunos.</li><li><span></span>Não me calo diante de violência, assédio ou discriminação.</li><li><span></span>Levo as minhas discordâncias aos canais próprios.</li><li><span></span>Reconheço os meus erros e procuro corrigi-los.</li></ul><div class=\"pratica\"><div class=\"tt\">Para praticar · para refletir</div><div class=\"q\"><b>1.</b> Que atitude sua, no trabalho, mais ensina os alunos pelo exemplo?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que situação da sua rotina exige mais cuidado ético?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> O que você se compromete a fazer de diferente a partir de hoje?<div class=\"ln\"></div><div class=\"ln\"></div></div></div><div class=\"nota\"><b>Ética se constrói junto</b><br/>Leve um caso deste guia para discutir na próxima reunião da sua equipe. Conversar sobre situações concretas é o melhor modo de alinhar condutas.</div>"},{"id":"c29","titulo":"Termo de compromisso","html":"<div class=\"rapido\"><p>Declaro que li o guia de ética profissional da rede municipal de ensino e que me comprometo a:</p><ul class=\"chk\"><li><span></span>Tratar alunos, responsáveis e colegas com respeito e igualdade.</li><li><span></span>Proteger os alunos e comunicar à direção qualquer suspeita de violência.</li><li><span></span>Guardar sigilo sobre dados e situações de alunos, famílias e colegas.</li><li><span></span>Usar os bens, o tempo e os sistemas da escola apenas para o trabalho.</li><li><span></span>Recusar vantagens e comunicar condutas inadequadas.</li></ul><p style=\"margin-top:8mm\">Nome: ____________________________________________ &nbsp; Matrícula: ________________</p><p>Função: _____________________________ &nbsp; Escola ou setor: _______________________________</p><p>Data: ____/____/________ &nbsp;&nbsp; Assinatura: _____________________________________________</p></div>"},{"id":"c30","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Um colega pede que você registre a presença dele. Você deve:</p><ol type=\"a\"><li>Pedir algo em troca.</li><li>Registrar, por amizade.</li><li>Recusar.</li><li>Registrar e avisar depois.</li></ol></div><div class=\"qz\"><p><b>2.</b> Fotos de alunos podem ser publicadas:</p><ol type=\"a\"><li>Em qualquer rede social.</li><li>Nos canais oficiais, com autorização dos responsáveis.</li><li>No perfil pessoal do servidor.</li><li>Em grupos de mensagens.</li></ol></div><div class=\"qz\"><p><b>3.</b> Ao ver um colega humilhar um aluno, o adequado é:</p><ol type=\"a\"><li>Filmar e publicar.</li><li>Comentar com outros alunos.</li><li>Não se envolver.</li><li>Intervir com calma e comunicar à direção.</li></ol></div><div class=\"qz\"><p><b>4.</b> O princípio da impessoalidade significa:</p><ol type=\"a\"><li>Tratar todos da mesma forma, sem favorecer nem perseguir.</li><li>Não assinar documentos.</li><li>Trabalhar sem identificação.</li><li>Não conversar com ninguém.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> c) Recusar. Registro falso é falta grave.</p><p><b>2.</b> b) Nos canais oficiais, com autorização dos responsáveis. A imagem do aluno é protegida.</p><p><b>3.</b> d) Intervir com calma e comunicar à direção. A proteção do aluno vem primeiro.</p><p><b>4.</b> a) Tratar todos da mesma forma, sem favorecer nem perseguir. Igualdade no atendimento.</p></div>"},{"id":"c31","titulo":"Glossário","html":"<dl><dt>Assédio moral</dt><dd>Conduta repetida que humilha ou constrange alguém no trabalho.</dd><dt>Assédio sexual</dt><dd>Constrangimento com conduta de natureza sexual não desejada.</dd><dt>Conflito de interesses</dt><dd>Situação em que um ganho pessoal pode influenciar uma decisão do trabalho.</dd><dt>Dado pessoal sensível</dt><dd>Informação sobre saúde, origem racial, religião e outras que exigem proteção reforçada.</dd><dt>Estatuto do servidor</dt><dd>Lei do Município que define direitos, deveres e medidas disciplinares dos servidores.</dd><dt>Impessoalidade</dt><dd>Princípio de tratar todos igualmente, sem favorecer nem perseguir.</dd><dt>Improbidade</dt><dd>Ato desonesto no exercício da função pública, com sanções previstas em lei.</dd><dt>Laicidade</dt><dd>Separação entre o Estado e as religiões, com respeito a todas as crenças.</dd><dt>Nepotismo</dt><dd>Favorecimento de parentes em nomeações e contratações.</dd><dt>Ouvidoria</dt><dd>Canal que recebe reclamações, denúncias e sugestões dos cidadãos e dos servidores.</dd><dt>Processo disciplinar</dt><dd>Procedimento que apura faltas funcionais, com direito de defesa.</dd><dt>Retaliação</dt><dd>Punição ou prejuízo imposto a quem relatou um problema.</dd><dt>Sigilo</dt><dd>Dever de não divulgar o que se conhece em razão do trabalho.</dd><dt>Unidade executora</dt><dd>Entidade da escola que recebe e administra recursos, como o conselho escolar.</dd></dl>"}];

